// QwibiServiceServer is the server API for QwibiService service.
// All implementations should embed UnimplementedQwibiServiceServer
// for forward compatibility.
//
// QwibiService is the single public surface of qwibi.v1. Authentication is
// carried in gRPC metadata ("authorization: Bearer <access_token>"), validated
// by an auth middleware that resolves the token against the Redis session cache
// and enforces per-RPC and per-layer authorization. Most methods require a valid
// access token; the exceptions are open (no token) or optional (the result is
// richer when authenticated, but a token is not required) and are marked as such
// in each method's own comment below.
//
// Idempotency ("x-request-id"): a unary mutation the client may retry can carry
// an "x-request-id" gRPC metadata header — an opaque, client-generated key of at
// most 64 characters (a UUID is typical). The server dedupes the create and
// delete RPCs on (account, method, x-request-id) within a 15-minute window:
//   - a duplicate that arrives while the first attempt is still executing fails
//     with ABORTED "request in flight, retry later" (back off and retry);
//   - a duplicate after the first attempt completed replays the stored first
//     response byte-for-byte (if that response was too large to cache, the
//     duplicate fails with ABORTED "idempotent replay unavailable" — the write
//     still happened exactly once).
//
// Reuse ONE id across retries of ONE logical operation; never share an id
// between different operations. The header is echoed back as an "x-request-id"
// response header for correlation. It never influences authentication or
// authorization; requests without it execute unconditionally (no dedupe), and
// streaming RPCs ignore it. Updates/moves need no request id — they are
// retry-safe via expected_version (compare-and-set) — and object writes keyed
// by hid have a stronger, window-free idempotency: see PostObject/PostObjects
// upsert-by-hid, the canonical idempotent object write.
type QwibiServiceServer interface {
	// Authenticate exchanges a Credential for a Session. Open (no token required).
	Authenticate(context.Context, *AuthenticateRequest) (*AuthenticateResponse, error)
	// RefreshToken rotates a Session from a refresh token. Open (no access token).
	RefreshToken(context.Context, *RefreshTokenRequest) (*RefreshTokenResponse, error)
	// Logout revokes the session represented by the caller's access token.
	Logout(context.Context, *LogoutRequest) (*LogoutResponse, error)
	// RevokeSession revokes another session owned by the caller.
	RevokeSession(context.Context, *RevokeSessionRequest) (*RevokeSessionResponse, error)
	// ListMySessions lists the caller's live sign-in sessions, the one presenting
	// the token included and marked current. Account principals only.
	ListMySessions(context.Context, *ListMySessionsRequest) (*ListMySessionsResponse, error)
	// RevokeOtherSessions ends every live session of the caller except the one
	// presenting the token. Account principals only.
	RevokeOtherSessions(context.Context, *RevokeOtherSessionsRequest) (*RevokeOtherSessionsResponse, error)
	// AddBasicCredential attaches an email/password login to the caller's account.
	AddBasicCredential(context.Context, *AddBasicCredentialRequest) (*AddBasicCredentialResponse, error)
	// RequestMagicLink emails a single-use sign-in link to an address (passwordless
	// login). Open (no token required); the reply is uniform so it never reveals
	// whether the address is registered.
	RequestMagicLink(context.Context, *RequestMagicLinkRequest) (*RequestMagicLinkResponse, error)
	// VerifyMagicLink exchanges a magic-link token for a Session (like
	// Authenticate). Open (no token required); when a valid access token is also
	// presented it links the email to that account, upgrading an anonymous account
	// in place rather than creating a new one.
	VerifyMagicLink(context.Context, *VerifyMagicLinkRequest) (*VerifyMagicLinkResponse, error)
	// CreateOrganization creates an org owned by the authenticated caller.
	// Retry-safe with an "x-request-id" header (see the service comment).
	CreateOrganization(context.Context, *CreateOrganizationRequest) (*CreateOrganizationResponse, error)
	// GetOrganization fetches an org by id or hid.
	GetOrganization(context.Context, *GetOrganizationRequest) (*GetOrganizationResponse, error)
	// ListMyOrganizations lists the orgs the caller belongs to.
	ListMyOrganizations(context.Context, *ListMyOrganizationsRequest) (*ListMyOrganizationsResponse, error)
	// AddOrganizationMember adds an account to the org (owner/admin only).
	AddOrganizationMember(context.Context, *AddOrganizationMemberRequest) (*AddOrganizationMemberResponse, error)
	// ListOrganizationMembers returns the org roster (members only).
	ListOrganizationMembers(context.Context, *ListOrganizationMembersRequest) (*ListOrganizationMembersResponse, error)
	// UpdateOrganization partially updates an org's name/handle (owner/admin).
	UpdateOrganization(context.Context, *UpdateOrganizationRequest) (*UpdateOrganizationResponse, error)
	// RemoveOrganizationMember removes a member (owner/admin, or self); the last
	// owner cannot be removed.
	RemoveOrganizationMember(context.Context, *RemoveOrganizationMemberRequest) (*RemoveOrganizationMemberResponse, error)
	// DeleteOrganization deletes an org with no live apps (owner only) —
	// memberships and the org row go synchronously; apps must be deleted first.
	DeleteOrganization(context.Context, *DeleteOrganizationRequest) (*DeleteOrganizationResponse, error)
	// Creates one permanent or bounded organization credential. Human owner or
	// administrator only. x-request-id is mandatory and is claimed durably; the
	// one-time secret is never replayed.
	CreateOrganizationAccessKey(context.Context, *CreateOrganizationAccessKeyRequest) (*CreateOrganizationAccessKeyResponse, error)
	// Lists non-secret key metadata for one organization (owner/admin only).
	ListOrganizationAccessKeys(context.Context, *ListOrganizationAccessKeysRequest) (*ListOrganizationAccessKeysResponse, error)
	// Revokes one organization credential and completes its serving barrier.
	RevokeOrganizationAccessKey(context.Context, *RevokeOrganizationAccessKeyRequest) (*RevokeOrganizationAccessKeyResponse, error)
	// CreateApp registers a geo-application owned by an organization.
	// Retry-safe with an "x-request-id" header (see the service comment).
	CreateApp(context.Context, *CreateAppRequest) (*CreateAppResponse, error)
	// GetApp fetches an app by id or hid.
	GetApp(context.Context, *GetAppRequest) (*GetAppResponse, error)
	// UpdateApp partially updates an app.
	UpdateApp(context.Context, *UpdateAppRequest) (*UpdateAppResponse, error)
	// RetireApp terminally retires an App without deleting any retained
	// reference or Layer.
	RetireApp(context.Context, *RetireAppRequest) (*RetireAppResponse, error)
	// DeleteApp physically deletes an already retired App only when its complete
	// reference inventory is empty. It never retires the App or deletes a Layer.
	DeleteApp(context.Context, *DeleteAppRequest) (*DeleteAppResponse, error)
	// AddAppPublisherGrant creates one explicit grant row. The caller needs an
	// effective PUBLISHER_ADMIN grant and the target must be a live human member
	// of the App's publisher organization.
	AddAppPublisherGrant(context.Context, *AddAppPublisherGrantRequest) (*AddAppPublisherGrantResponse, error)
	// RemoveAppPublisherGrant deletes one exact grant row and refuses to remove
	// the last effective live PUBLISHER_ADMIN.
	RemoveAppPublisherGrant(context.Context, *RemoveAppPublisherGrantRequest) (*RemoveAppPublisherGrantResponse, error)
	// ListAppPublisherGrants returns explicit grant rows in stable uid order.
	// Holding any effective grant on the App is sufficient.
	ListAppPublisherGrants(context.Context, *ListAppPublisherGrantsRequest) (*ListAppPublisherGrantsResponse, error)
	// CreateAppToken mints a long-lived token letting the app act via the API.
	// Retry-safe with an "x-request-id" header (see the service comment).
	CreateAppToken(context.Context, *CreateAppTokenRequest) (*CreateAppTokenResponse, error)
	// ListAppTokens lists an app's minted tokens (metadata only; owner only).
	ListAppTokens(context.Context, *ListAppTokensRequest) (*ListAppTokensResponse, error)
	// RevokeAppToken revokes a token by id so it no longer authenticates (owner only).
	RevokeAppToken(context.Context, *RevokeAppTokenRequest) (*RevokeAppTokenResponse, error)
	// ListPublicApps lists public, catalog-discoverable apps.
	ListPublicApps(context.Context, *ListPublicAppsRequest) (*ListPublicAppsResponse, error)
	// ReserveLayerBlobUpload declares immutable Layer/content facts and returns
	// only a relative upload path on the Qwibi origin.
	ReserveLayerBlobUpload(context.Context, *ReserveLayerBlobUploadRequest) (*ReserveLayerBlobUploadResponse, error)
	// CompleteLayerBlobUpload seals bytes for the exact Layer and content hash.
	CompleteLayerBlobUpload(context.Context, *CompleteLayerBlobUploadRequest) (*CompleteLayerBlobUploadResponse, error)
	// DeleteLayerBlob requests deletion of the exact Layer-bound content.
	DeleteLayerBlob(context.Context, *DeleteLayerBlobRequest) (*DeleteLayerBlobResponse, error)
	// IssueLayerBlobRead derives a one-use Qwibi read path from one GeoObject
	// reference. The service does not expose provider URLs or reads by blob ID.
	IssueLayerBlobRead(context.Context, *IssueLayerBlobReadRequest) (*IssueLayerBlobReadResponse, error)
	// CreateAccount registers a new account profile.
	// Retry-safe with an "x-request-id" header (see the service comment).
	CreateAccount(context.Context, *CreateAccountRequest) (*CreateAccountResponse, error)
	// GetAccount fetches an account (or the caller's own when id is empty).
	GetAccount(context.Context, *GetAccountRequest) (*GetAccountResponse, error)
	// UpdateAccount partially updates an account.
	UpdateAccount(context.Context, *UpdateAccountRequest) (*UpdateAccountResponse, error)
	// DeleteAccount deletes the CALLER's account (GDPR): status→deleted + PII
	// scrubbed + sessions dead in one transaction; authored objects anonymized
	// asynchronously (content kept); blocked while the caller still owns an org
	// with other members.
	DeleteAccount(context.Context, *DeleteAccountRequest) (*DeleteAccountResponse, error)
	// CheckHandleAvailable reports whether a public @handle is free to claim — for
	// live availability feedback in the profile editor.
	CheckHandleAvailable(context.Context, *CheckHandleAvailableRequest) (*CheckHandleAvailableResponse, error)
	// BlockAccount idempotently creates a symmetric-in-effect moderation edge.
	BlockAccount(context.Context, *BlockAccountRequest) (*BlockAccountResponse, error)
	// UnblockAccount idempotently removes the caller's block edge.
	UnblockAccount(context.Context, *UnblockAccountRequest) (*UnblockAccountResponse, error)
	// MuteAccount idempotently hides one account's content from the caller.
	MuteAccount(context.Context, *MuteAccountRequest) (*MuteAccountResponse, error)
	// UnmuteAccount idempotently removes the caller's mute edge.
	UnmuteAccount(context.Context, *UnmuteAccountRequest) (*UnmuteAccountResponse, error)
	// ListAccountRelations lists only the caller's outgoing relations.
	ListAccountRelations(context.Context, *ListAccountRelationsRequest) (*ListAccountRelationsResponse, error)
	// RegisterPushToken registers or refreshes a delivery endpoint for the caller.
	RegisterPushToken(context.Context, *RegisterPushTokenRequest) (*RegisterPushTokenResponse, error)
	// UnregisterPushToken permanently removes one token owned by the caller.
	UnregisterPushToken(context.Context, *UnregisterPushTokenRequest) (*UnregisterPushTokenResponse, error)
	// ListPushTokens returns only non-sensitive metadata for the caller's tokens.
	ListPushTokens(context.Context, *ListPushTokensRequest) (*ListPushTokensResponse, error)
	// SetLayerNotifyPolicy updates the caller's own membership notification policy.
	SetLayerNotifyPolicy(context.Context, *SetLayerNotifyPolicyRequest) (*SetLayerNotifyPolicyResponse, error)
	// CreateLayer creates a layer owned by the caller.
	// Retry-safe with an "x-request-id" header (see the service comment).
	CreateLayer(context.Context, *CreateLayerRequest) (*CreateLayerResponse, error)
	// TransferLayerOwnership atomically moves ownership between active humans.
	TransferLayerOwnership(context.Context, *TransferLayerOwnershipRequest) (*TransferLayerOwnershipResponse, error)
	// AssignReservedLayerHumanID is the sole v1 platform-administrator action.
	AssignReservedLayerHumanID(context.Context, *AssignReservedLayerHumanIDRequest) (*AssignReservedLayerHumanIDResponse, error)
	// GetLayer fetches a single layer (objects are not inlined; use Query), by
	// immutable UUID or global HID.
	GetLayer(context.Context, *GetLayerRequest) (*GetLayerResponse, error)
	// ResolveLayerHumanID resolves one global Layer HID without an App namespace.
	ResolveLayerHumanID(context.Context, *ResolveLayerHumanIDRequest) (*ResolveLayerHumanIDResponse, error)
	// ResolvePath resolves one v1 resource path — "<layer_hid>" alone or
	// "<layer_hid>/<object_hid>" — to the immutable UUIDs, the canonical current
	// human IDs and the per-segment redirect fact, in one round trip. Optional (a
	// token is required only to reach a private path). An unauthorized path and an
	// unknown path return the identical NotFound, so resolution reveals no
	// protected metadata.
	ResolvePath(context.Context, *ResolvePathRequest) (*ResolvePathResponse, error)
	// UpdateLayer partially updates a layer.
	UpdateLayer(context.Context, *UpdateLayerRequest) (*UpdateLayerResponse, error)
	// DeleteLayer soft-deletes a layer (layer owner, app owner or org admin):
	// gone from reads immediately, one LayerDeleted to live subscribers, objects
	// purged asynchronously.
	DeleteLayer(context.Context, *DeleteLayerRequest) (*DeleteLayerResponse, error)
	// ArchiveLayer makes a layer read-only and closed to new membership while
	// preserving its data, memberships, and resume history.
	ArchiveLayer(context.Context, *ArchiveLayerRequest) (*ArchiveLayerResponse, error)
	// UnarchiveLayer restores writes and membership changes to a layer.
	UnarchiveLayer(context.Context, *UnarchiveLayerRequest) (*UnarchiveLayerResponse, error)
	// JoinLayer joins the caller to a layer, returning the granted membership.
	JoinLayer(context.Context, *JoinLayerRequest) (*JoinLayerResponse, error)
	// CreateInvite mints an invite token granting a role on the layer.
	// Retry-safe with an "x-request-id" header (see the service comment).
	CreateInvite(context.Context, *CreateInviteRequest) (*CreateInviteResponse, error)
	// ListMembers returns the roster of a layer (members only).
	ListMembers(context.Context, *ListMembersRequest) (*ListMembersResponse, error)
	// UpdateReadCursor monotonically advances the caller's own approximate
	// per-layer read position and clamps it to the current layer head.
	UpdateReadCursor(context.Context, *UpdateReadCursorRequest) (*UpdateReadCursorResponse, error)
	// UpdateMemberRole changes a member's role (owner/editor only).
	UpdateMemberRole(context.Context, *UpdateMemberRoleRequest) (*UpdateMemberRoleResponse, error)
	// RemoveMember removes a member from the layer (owner/editor only).
	RemoveMember(context.Context, *RemoveMemberRequest) (*RemoveMemberResponse, error)
	// LeaveLayer removes the caller's own membership.
	LeaveLayer(context.Context, *LeaveLayerRequest) (*LeaveLayerResponse, error)
	// PostObject creates a new object on a layer. The mutation and its outbox
	// event commit in one transaction so the real-time feed never diverges from
	// stored state.
	//
	// Upsert-by-hid (`upsert = true` with an ObjectWrite.hid) is THE canonical
	// idempotent object write: re-running the same call converges on the one
	// object keyed by that hid, with no time window. Prefer it for any write that
	// can repeat (ingest, reconciliation, bots). A create without a hid is
	// retry-safe only via an "x-request-id" header (see the service comment).
	PostObject(context.Context, *PostObjectRequest) (*PostObjectResponse, error)
	// PostObjects creates many objects on one layer in a single transaction (all or
	// nothing) — for bulk ingest, e.g. a fleet of vehicle positions per tick.
	// Upsert-by-hid is the canonical idempotent bulk write (see PostObject); an
	// "x-request-id" header covers retried batches without hids.
	PostObjects(context.Context, *PostObjectsRequest) (*PostObjectsResponse, error)
	// GetObject fetches a single object by id.
	GetObject(context.Context, *GetObjectRequest) (*GetObjectResponse, error)
	// UpdateObject replaces the mutable fields of an object.
	UpdateObject(context.Context, *UpdateObjectRequest) (*UpdateObjectResponse, error)
	// MoveObject changes only an object's geometry. Ledger movement emits a durable
	// ObjectMoved delta; streamed movement applies a last-write-wins position tick
	// without an outbox append.
	MoveObject(context.Context, *MoveObjectRequest) (*MoveObjectResponse, error)
	// MoveObjects repositions many objects on one layer. Ledger movement is one
	// all-or-nothing transaction and emits ObjectMoved deltas. Streamed movement
	// prevalidates the batch, then applies last-write-wins ticks without an outbox
	// append; an operational rejection can follow already accepted ticks.
	MoveObjects(context.Context, *MoveObjectsRequest) (*MoveObjectsResponse, error)
	// DeleteObject removes an object.
	DeleteObject(context.Context, *DeleteObjectRequest) (*DeleteObjectResponse, error)
	// ListMyApps lists apps owned by the caller.
	ListMyApps(context.Context, *ListMyAppsRequest) (*ListMyAppsResponse, error)
	// ListDiscoverableLayers returns the fixed anonymously readable, curated
	// Layer catalog without enumerating an App parent.
	ListDiscoverableLayers(context.Context, *ListDiscoverableLayersRequest) (*ListDiscoverableLayersResponse, error)
	// ListMyLayers returns the authenticated human's owned and active-joined
	// Layer workspace without enumerating an App parent.
	ListMyLayers(context.Context, *ListMyLayersRequest) (*ListMyLayersResponse, error)
	// ListObjects lists objects in a layer (keyset paginated, non-spatial).
	ListObjects(context.Context, *ListObjectsRequest) (*ListObjectsResponse, error)
	// Query returns objects within one layer matching a spatial (and optional
	// property) filter, H3-cell + PostGIS ST_ refinement, with keyset pagination.
	Query(context.Context, *QueryRequest) (*QueryResponse, error)
	// Search discovers layers across the catalog by text/proximity.
	Search(context.Context, *SearchRequest) (*SearchResponse, error)
	// Subscribe is the bidirectional real-time channel. The client streams
	// viewport/layer/presence updates (SubscribeRequest); the server streams a
	// snapshot followed by ordered deltas, presence, heartbeats, and in-band
	// errors (ServerEvent). See subscribe.proto and events.proto.
	Subscribe(grpc.BidiStreamingServer[SubscribeRequest, ServerEvent]) error
	// StreamLayer is the server-streaming half of Subscribe for clients that
	// cannot open a bidirectional stream (browsers over gRPC-Web/Connect). The
	// client opens it with a single SubscribeRequest (layer_ids + viewport, and
	// optionally options) and the server streams the same snapshot + deltas +
	// presence. It is unidirectional: there is no client->server channel, so the
	// caller cannot push presence pings or re-target the viewport (re-open the
	// stream to change the viewport).
	StreamLayer(*SubscribeRequest, grpc.ServerStreamingServer[ServerEvent]) error
	// GetSnapshot returns the canonical cached subscription seed from the primary:
	// snapshot(as-of C) plus bounded durable replay after C. The gateway attaches
	// its own live hub route first, calls this RPC, applies snapshot then replay,
	// and drains the buffered live tail; this keeps edge snapshots in the same
	// cursor space without duplicating database/caching logic at the edge.
	GetSnapshot(context.Context, *GetSnapshotRequest) (*GetSnapshotResponse, error)
	// BackfillDeltas replays the deltas a subscriber missed since a resume cursor,
	// scoped to its viewport, from the durable event log. It backs an edge that runs
	// the live delta fan-out itself but has no database of its own (the gateway): on
	// reconnect the edge calls this to diff forward from the client's cursor instead
	// of re-sending a full snapshot. `complete` is false when the gap is too large to
	// diff cheaply or the cursor is from an older sequence space — the caller then
	// falls back to a snapshot. The server clamps the replay to the safe resume floor,
	// so a raw last-seen seq is honored without skipping a late-committing lower seq.
	BackfillDeltas(context.Context, *BackfillDeltasRequest) (*BackfillDeltasResponse, error)
	// SendPresence broadcasts a presence signal (e.g. typing, live cursor) for the
	// caller on a layer. It is the unidirectional presence uplink for StreamLayer
	// consumers, which have no client->server channel of their own; bidirectional
	// Subscribe clients carry the same signal inline via SubscribeRequest.presence.
	SendPresence(context.Context, *SendPresenceRequest) (*SendPresenceResponse, error)
}

